package com.collabcase.agent;import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.collabcase.agent.dto.AgentDtos.*;import com.collabcase.user.User;import jakarta.validation.Valid;
@RestController @RequestMapping("/api/agent") public class CollabCaseAgentController{private final CollabCaseAgentService service;public CollabCaseAgentController(CollabCaseAgentService service){this.service=service;}@PostMapping("/chat")public ChatResponse chat(@Valid @RequestBody ChatRequest request,@AuthenticationPrincipal User user){return service.chat(request,user.getId());}@GetMapping("/status")public Status status(){return service.status();}}
